<template>
 <view class="wallet-panel">
  <view v-if="error" class="card error">{{error}}<button class="ui-button" :disabled="busy" @click="load">刷新充值记录</button></view>
  <template v-if="account">
   <view class="balance"><text>小程序可用余额</text><view class="amount">¥{{money(account.available)}}</view><view>{{account.membership.tier?discount(account.membership.rate)+'消费优惠':'尚未开通充值消费优惠'}}</view><text v-if="account.reserved">待付款订单占用 ¥{{money(account.reserved)}}</text><view v-if="account.refundReserved">充值退款冻结 ¥{{money(account.refundReserved)}}</view></view>
   <view class="hint intro">仅计入本小程序微信充值，与线下门店的余额分开。充值不送消费积分，买商品时按实际划扣金额计算。</view>
   <view class="heading">微信充值</view>
   <view class="hint">{{account.settings.upgradeMode==='single'?'按单笔充值定折扣，多次充值不合并升级。保留已到账、未退款充值中的最高档。':'按本小程序累计已到账、未退款充值升级。'}}</view>
   <view v-if="!isWechat" class="card hint">请进入微信小程序使用微信充值。这里可以查看余额和充值记录。</view>
   <view v-else-if="!account.ready" class="card hint">商家暂未开放微信充值，已有余额仍可用于消费。</view>
   <view class="tiers"><button v-for="tier in account.settings.tiers" :key="tier.id" class="tier" :class="{selected:selectedId===tier.id}" :disabled="busy||!account.ready||!isWechat||!!pending.length||!!uncertainIntent" @click="selectedId=tier.id"><text class="tier-amount">¥{{money(tier.amount)}}</text><text>{{discount(tier.rate)}}</text></button></view>
   <view v-if="selectedTier" class="card hint">本次微信支付 ¥{{money(selectedTier.amount)}}，到账后增加等额小程序余额。{{account.settings.upgradeMode==='single'?'本次单笔充值对应'+discount(selectedTier.rate)+'，已有更高优惠继续保留。':'到账后按累计充值总额计算消费折扣。'}}</view>
   <button v-if="isWechat&&account.ready&&!pending.length&&!uncertainIntent" class="ui-button primary" :disabled="busy||!selectedTier" @click="start">{{busy?'正在确认充值':'确认金额，微信充值'}}</button>
   <view v-if="uncertainIntent" class="card"><view>上一笔 ¥{{money(uncertainIntent.expectedAmount)}} 充值提交结果待确认。</view><button class="ui-button" :disabled="busy||!isWechat" @click="retryIntent">继续核对这笔充值</button></view>
   <view class="between heading"><text>充值记录</text><text class="refresh" @click="load">刷新</text></view>
   <view v-if="!account.recharges.length" class="card hint">还没有小程序充值记录。</view>
   <view v-for="row in account.recharges" :key="row.id" class="card"><view class="between"><text>微信充值 ¥{{money(row.amount)}}</text><text>{{stateLabel(row)}}</text></view><view class="small">{{formatDate(row.paid_at||row.created_at)}}</view><view class="small number">{{row.out_trade_no}}</view><view v-if="['CREATING','READY'].includes(row.state)" class="actions"><button v-if="isWechat&&account.ready" :disabled="busy" @click="resume(row)">继续付款</button><button :disabled="busy" @click="check(row)">查询到账</button><button :disabled="busy" @click="close(row)">关闭</button></view></view>
   <view class="heading">小程序余额明细</view><view v-if="!account.ledger.length" class="card hint">暂时没有余额变动。</view>
   <view v-for="(row,i) in account.ledger" :key="i" class="card"><view class="between"><text>{{row.title||names[row.kind]||'余额变动'}}</text><text>{{row.delta>0?'+':''}}{{money(row.delta)}}元</text></view><view>{{row.note}}</view><view class="small">{{formatDate(row.created_at)}}</view></view>
   <view v-if="legacy&&(legacy.available||legacy.reserved||legacy.ledger?.length)" class="card legacy"><view class="heading">门店余额</view><view>可用 ¥{{money(legacy.available)}}<text v-if="legacy.reserved">，订单占用 ¥{{money(legacy.reserved)}}</text></view><view class="hint">在门店付款、由店员登记的充值记在这里，下单时打开「使用门店余额」抵扣，零售和拿货都能用；不并入小程序充值余额，也不参加充值折扣升级。</view><view v-for="(row,i) in legacy.ledger" :key="i" class="legacy-row"><view class="between"><text>{{row.title||names[row.kind]||'余额变动'}}</text><text>{{money(row.delta)}}元</text></view><view class="small">{{formatDate(row.created_at)}} · {{row.note}}</view></view></view>
  </template>
 </view>
</template>
<script>
import {request,money,notify} from '../services/shop.js'
import {formatDate} from '../services/display.js'
import {createRecharge,payRecharge,reconcileRechargeIntent} from '../services/wechat-recharge.js'
export default {props:{refreshTick:{default:0}},watch:{refreshTick(){this.load()}},data(){return{account:null,legacy:null,busy:false,error:'',selectedId:'',isWechat:false,uncertainIntent:null,names:{online_recharge:'微信充值到账',online_refund_hold:'充值退款冻结',online_refund_release:'充值退款关闭返还',recharge:'原余额入账',hold:'消费划扣／订单占用',release:'订单取消返还',payment:'完成支付',refund:'商品退款返还',store_topup:'门店充值',store_topup_void:'门店充值作废',store_refund:'门店余额退款'}}},computed:{selectedTier(){return this.account?.settings.tiers.find(t=>t.id===this.selectedId)},pending(){return(this.account?.recharges||[]).filter(r=>['CREATING','READY'].includes(r.state))}},mounted(){
 // #ifdef MP-WEIXIN
 this.isWechat=true
 // #endif
 this.load()
},methods:{money,formatDate,discount(rate){return Number(rate)/1000+'折'},stateLabel(r){return r.refund_state?({QUEUED:'退款待确认',PROCESSING:'退款中',ABNORMAL:'退款待商家核实',SUCCESS:'已原路退款',CLOSED:'退款已关闭'}[r.refund_state]||'退款待核实'):({SUCCESS:'已到账',CLOSED:'已关闭',CREATING:'待付款确认',READY:'待付款'}[r.state]||'待确认')},async load(){try{this.account=await request('/retail-recharge');this.uncertainIntent=reconcileRechargeIntent(this.account.recharges);this.error='';this.legacy=await request('/wallet')}catch(e){this.error=e.message}},async run(fn){if(this.busy)return;this.busy=true;let failure;try{await fn()}catch(e){failure=e;notify(e)}finally{await this.load();if(failure)this.error=failure.message;this.busy=false}},async start(){if(!this.isWechat||!this.selectedTier)return;const tier=this.selectedTier;await this.run(async()=>{const row=await createRecharge(tier,this.account.settings);await payRecharge(row.id);uni.showToast({title:'充值已到账',icon:'success'})})},async retryIntent(){if(!this.isWechat||!this.uncertainIntent)return;const intent=this.uncertainIntent;await this.run(async()=>{const row=await createRecharge({id:intent.tierId,amount:intent.expectedAmount},{version:intent.settingsVersion});await payRecharge(row.id)})},async resume(row){if(this.isWechat)await this.run(()=>payRecharge(row.id))},async check(row){await this.run(async()=>{const result=await request('/retail-recharge/'+row.id+'/status','POST',{});notify(result.paid?'充值已到账':'还未确认到账，已扣款请勿重复充值')})},async close(row){const answer=await new Promise(resolve=>uni.showModal({title:'关闭这笔待付款充值？',content:'系统会先向微信核对；如果已经支付，将正常入账。',success:resolve,fail:()=>resolve({confirm:false})}));if(answer.confirm)await this.run(()=>request('/retail-recharge/'+row.id+'/close','POST',{}))}}}
</script>
<style scoped>
@import '../styles/component-base.css';
.wallet-panel{padding:14px;font-size:14px;line-height:1.7}.balance{padding:24px;border-radius:14px;background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c)}.amount{font-size:34px;font-weight:600;margin:4px 0}.heading{margin:22px 0 12px;font-size:17px;font-weight:600}.card{padding:16px;margin:12px 0;border-radius:10px;background:var(--shop-surface, #fdfeff);line-height:1.8}.between{display:flex;justify-content:space-between;gap:12px}.small,.hint{font-size:12px;color:var(--shop-ink, #28546c)}.intro{margin-top:12px}.number{overflow-wrap:anywhere}.tiers{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;margin:14px 0}.tier{width:100%;box-sizing:border-box;margin:0;padding:14px 3px;border:1px solid var(--shop-border, #d5e6ee);background:var(--shop-surface, #fdfeff);border-radius:9px;text-align:center;line-height:1.8;font-size:13px}.tier text{display:block}.tier-amount{font-weight:600;font-size:15px}.tier.selected{border:2px solid var(--shop-control, #417c9a);background:var(--shop-soft, #eaf5fb);padding:13px 2px}.tier[disabled]{color:var(--shop-ink, #28546c)}.actions{display:flex;gap:8px;margin-top:12px}.actions button{flex:1;padding:0 6px;font-size:12px;line-height:36px;background:var(--shop-background, #f3f8fb);color:var(--shop-text, #2b424f)}.primary{background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c)}.refresh{font-size:13px;color:var(--shop-text, #2b424f)}.error{color:#a13a2c}.legacy-row{padding:12px 0;border-top:1px solid var(--shop-border, #d5e6ee)}.legacy .heading{margin-top:0}
</style>
